<?php auth();verify_csrf();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('checkout.php');$items=cart_items();if(!$items)redirect('cart.php');$subtotal=cart_total();[$discount,$coupon]=discount_for($_SESSION['coupon']??'', $subtotal);$shipping=(int)setting('shipping_cost',0);$total=max(0,$subtotal-$discount+$shipping);$pdo->beginTransaction();try{$s=$pdo->prepare('INSERT INTO orders(user_id,receiver,phone,address,subtotal,discount,shipping,total,payment_method,status) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([user()['id'],trim($_POST['receiver']),trim($_POST['phone']??''),trim($_POST['address']),$subtotal,$discount,$shipping,$total,$_POST['payment']==='online'?'online':'cod','pending']);$oid=$pdo->lastInsertId();$si=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,price,qty) VALUES(?,?,?,?,?)');$up=$pdo->prepare('UPDATE products SET stock=stock-?, sales=sales+? WHERE id=? AND stock>=?');foreach($items as $p){$si->execute([$oid,$p['id'],$p['name'],$p['price'],$p['qty']]);$up->execute([$p['qty'],$p['qty'],$p['id'],$p['qty']]);if($up->rowCount()===0)throw new Exception('موجودی کافی نیست');}if($coupon)$pdo->prepare('UPDATE coupons SET used_count=used_count+1 WHERE id=?')->execute([$coupon['id']]);$pdo->commit();$_SESSION['cart']=[];unset($_SESSION['coupon']);redirect('order.php?id='.$oid);}catch(Throwable $e){$pdo->rollBack();flash('err','ثبت سفارش انجام نشد: '.$e->getMessage());redirect('checkout.php');}
